templates.template:
/* =============================================================================
   Simplex — a XenForo 2.3 port of the ProBoards "Simplex" skin by Allan of Skins n Things.
   Dotted grey page, a silver column with orange edges, orange-rimmed category bars and silver title bars.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */
html
{
	background: url("data:image/png;base64,") center top / 840px 1px repeat-y fixed, url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAABnRSTlMAAAAAAABupgeRAAAANUlEQVR42r3MQQ0AMAgDwGzBCv7VIKNtigK+CwL2u9edqgJAMjNfXACSbC8ESdvdvRBr+FoNHWqf9iMiL6UAAAAASUVORK5CYII=") repeat #aaaaaa;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The 800px framed column -------------------------------------------------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 800px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner
{
	background: transparent;
	padding-left: 0px;
	padding-right: 0px;
}

.p-header-content
{
	justify-content: center;
	padding: 4px 0 8px;
}

// The skin's banner replaces the logo. Delete this section to use the logo from Style properties.
.p-header-logo
{
	margin: 0 auto;

	img
	{
		display: none;
	}

	a
	{
		display: block;
		width: 800px;
		max-width: 100%;
		aspect-ratio: 800 / 100;
		background: url("data:image/gif;base64,") center / contain no-repeat;
	}
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

// ---- Menu bar ---------------------------------------------------------------------------

.p-nav
{
	color: #202020;
}

.p-nav-inner
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x content-box, transparent;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #202020;
		font-size: 11px;
		font-weight: 700;
		letter-spacing: 1px;
		text-transform: uppercase;
		text-shadow: 0 1px 0 #ffffff;

		&:hover
		{
			color: #ae5302;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(255, 255, 255, .14);

		.p-navEl-link
		{
			color: #ae5302;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #202020;

	&:hover
	{
		background: rgba(255, 255, 255, .14);
		color: #ae5302;
		text-decoration: none;
	}
}

.p-sectionLinks-inner a,
.p-breadcrumbs a
{
	color: #ae5302;
}

.p-body-inner
{
	color: #202020;
	padding-bottom: 16px;
}

.p-title-value,
.p-breadcrumbs
{
	color: #202020;
}

// ---- Blocks: the skin's category head, middle and base images around every block --------

.block-container
{
	background: url("data:image/gif;base64,") center top / 100% 20px repeat-y;
	border: none;
	border-radius: 0;
	padding: 0 2.5%;

	&::before,
	&::after
	{
		content: '';
		display: block;
		height: 20px;
		margin: 0 -2.5%;
		background: url("data:image/gif;base64,") center top / 100% 20px no-repeat;
	}

	&::after
	{
		height: 20px;
		background: url("data:image/gif;base64,") center top / 100% 20px no-repeat;
	}
}

.block-body,
.block-row
{
	background: #d6d4d4;
	color: #202020;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x, #d4d4d4;
	border-bottom: 1px solid #404040;
	color: #202020;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #202020;
	}

	.block-desc
	{
		color: #202020;
		opacity: .8;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #202020;
	opacity: .75;

	&:hover,
	&.is-active
	{
		opacity: 1;
		border-color: #202020;
	}
}

.block-footer
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x, #d4d4d4;
	border-top: 1px solid #404040;
	color: #202020;

	a
	{
		color: #202020;
	}
}

.node + .node
{
	border-top: 1px solid #404040;
}

.node-body,
.structItem
{
	background: #d6d4d4;
}

.structItem
{
	border-top-color: #404040;
}

.node-title a,
.structItem-title a
{
	color: #ae5302;
	font-weight: 700;

	&:hover
	{
		color: #da3e00;
	}
}

.node-description,
.node-meta,
.node-stats,
.structItem-minor
{
	color: #202020;
}

// Forum icons: the skin's new-posts image when there's something unread, otherwise no-new-posts.
.node--forum .node-icon i
{
	display: block;
	width: 20px;
	height: 20px;
	margin: 0 auto;
	background: url("data:image/gif;base64,") center / contain no-repeat;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/gif;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: #ae5302;
	}
}

.message,
.message-inner
{
	background: #d6d4d4;
	border-color: #404040;
}

.message-cell--user
{
	background: #dddbdb;
	border-right-color: #404040;
}

.message-userArrow::after
{
	border-right-color: #d6d4d4;
}

.button.button--primary,
a.button.button--primary
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x;
	background-color: #e4e4e4;
	border: 1px solid #404040;
	color: #202020;

	&:hover
	{
		color: #ae5302;
		filter: brightness(1.1);
	}
}

// ---- Footer -----------------------------------------------------------------------------

.p-footer
{
	background: transparent;
	color: #202020;

	a
	{
		color: #ae5302;
	}
}

.p-footer-copyright::after
{
	content: "Simplex skin by Allan of Skins n Things";
	display: block;
	margin-top: 4px;
}

// ---- Narrower than the frame: plain column, scaled banner ------------------------------

@media (max-width: 819px)
{
	.p-header
	{
		padding-top: 0;

		&::before
		{
			content: none;
		}
	}

	.p-header-inner,
	.p-nav-inner,
	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: rgba(214, 212, 212, .9);
		padding-left: 8px;
		padding-right: 8px;
	}

	.p-nav-inner
	{
		background: url("data:image/gif;base64,") left top / auto 100% repeat-x;
	}

	.p-footer::before
	{
		background-size: 100% auto;
	}
}
